public sealed class IslandThingSpec {
 public string id,name,description,kind; public int chapter,price; public float width,depth,height;
 public bool Building {get{return id.StartsWith("B");}}
 public string Resource {get{return "IslandExpansion/"+(Building?"Buildings/":"Decor/")+id;}}
}
public sealed class IslandItemSpec {public string id,name;public int buy,sell; public bool edible;}
public sealed class IslandRecipeSpec {
 public string id,name,building,output;public string[] inputs;public int[] amounts;public int count,seconds,chapter;
}
